  return known.find(state => value === state) || (/load|preparing|busy/.test(value) ? 'loading' : /error|fail|reject/.test(value) ? 'error' : /long/.test(value) ? 'long-text' : /empty|blank/.test(value) ? 'empty' : /overflow|above/.test(value) ? 'overflow' : /exact|valid/.test(value) ? 'exact' : /reconnect|retry/.test(value) ? 'recovery' : 'default');
