  const paths = {heart:'M12 20S3 14.5 3 8.5C3 3.5 9 2 12 6c3-4 9-2.5 9 2.5C21 14.5 12 20 12 20Z',print:'M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6z',link:'M10 15l4-6M9 16l-2 3a4 4 0 0 1-6-5l4-5a4 4 0 0 1 6 0M15 8l2-3a4 4 0 0 1 6 5l-4 5a4 4 0 0 1-6 0',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 17v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',check:'M5 12l5 5L20 6',sound:'M3 9h4l5-5v16l-5-5H3zM16 8c3 2 3 6 0 8M19 4c6 4 6 12 0 16',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',appearance:'M12 3a9 9 0 1 0 0 18V3Zm0 0a9 9 0 0 1 0 18'};
