  const geometry = {arch:'<path d="M13 84V42a37 37 0 0 1 74 0v42H66V58H34v26Z" fill="var(--orange)"/>',notch:'<path d="M12 14h57v18h20v53H12V62h18V43H12Z" fill="var(--yellow)"/>',wedge:'<path d="M9 83 40 12h25l27 71Z" fill="var(--mint)"/><path d="m66 12 26 71H68L53 43Z" fill="var(--action)"/>',loop:'<path d="M14 14h71v71H14Z M38 37v25h24V37Z" fill="var(--action)" fill-rule="evenodd"/><path d="M65 14h20v22H65z" fill="var(--orange)"/>'};
